                    if not assigned:
                        return False
                    for neighbor in graph[node]:
                        if neighbor in visited:
                            degree[neighbor] -= 1
                            if degree[neighbor] > 1:
                                heapq.heappush(pq, (-degree[neighbor], neighbor))

        return len(bad_cities) <= k

    low, high = 1, n - 1
    while low < high:
        mid = (low + high) // 2
        if is_valid(mid):
            high = mid
        else:
            low = mid + 1

    return low

def assign_roads(n, k, edges, r):
